                className="prose prose-sm max-w-none
                    text-[#efefd1]/90
                    prose-headings:text-[#efefd1]
                    prose-strong:text-[#efefd1]
                    prose-a:text-[#d8bd8a]
                    prose-hr:border-[#aa5042]
                    prose-li:marker:text-[#d8bd8a]"
                dangerouslySetInnerHTML={{ __html: html }}
            />
        </div>
    );
}

