const links = [
    { to: "/map", label: "Analyzer" },
    { to: "/about", label: "About" },
    { to: "/blog", label: "Blog" },
    { to: "/donate", label: "Donate" },
];

function NavBar() {
    const [isOpen, setIsOpen] = useState(false);
    const location = useLocation();

    useEffect(() => {
        setIsOpen(false);
    }, [location.pathname]);

    return (
        <nav className="relative">
            {/* Desktop: horizontal links */}
            <ul className="hidden md:flex space-x-6 text-lg text-[#efefd1]">
                {links.map(({ to, label }) => (
                    <li key={to}>
                        <Link to={to} className="hover:underline">
                            {label}
                        </Link>
                    </li>
                ))}
            </ul>

            {/* Mobile: hamburger button */}
            <button
                className="md:hidden text-[#efefd1] text-2xl leading-none p-1 select-none"
                onClick={() => setIsOpen((o) => !o)}
                aria-label={isOpen ? "Close menu" : "Open menu"}
                aria-expanded={isOpen}
            >
                {isOpen ? "✕" : "☰"}
            </button>

            {/* Mobile: dropdown */}
            {isOpen && (
                <div className="absolute right-0 top-full mt-2 bg-[#753742] border border-[#aa5042] rounded-lg shadow-xl z-50 py-2 min-w-[10rem] md:hidden">
                    {links.map(({ to, label }) => (
                        <Link
                            key={to}
                            to={to}
                            className="block px-4 py-2 text-[#efefd1] hover:bg-[#aa5042] text-base"
                        >
                            {label}
                        </Link>
                    ))}
                </div>
            )}
        </nav>
    );
}

export default NavBar;

import { useState } from "react";
import type { QuestionnaireAnswers } from "../types/questionnaire";
import type { Question } from "../lib/questionnaire";
import { ZONES, EMPTY_ANSWERS } from "../lib/questionnaire";

export default function QuestionnairePopup({
    onComplete,
}: {
    onComplete: (answers: QuestionnaireAnswers | null) => void;
}) {
    const [zoneIndex, setZoneIndex] = useState(0);
    const [answers, setAnswers] = useState<QuestionnaireAnswers>({ ...EMPTY_ANSWERS });

    const currentZone = ZONES[zoneIndex];
    const isLastZone = zoneIndex === ZONES.length - 1;

    function setSingle(field: Exclude<keyof QuestionnaireAnswers, "combustible_items_5ft">, value: string) {
        setAnswers((prev) => ({ ...prev, [field]: value }));
    }

    function toggleMulti(value: string) {
        setAnswers((prev) => {
            const current = prev.combustible_items_5ft ?? [];
            const next = current.includes(value)
                ? current.filter((v) => v !== value)
                : [...current, value];
            return { ...prev, combustible_items_5ft: next.length > 0 ? next : null };
        });
    }

    function handleNext() {
        if (isLastZone) {
            onComplete(answers);
        } else {
            setZoneIndex((i) => i + 1);
        }
    }

    return (
        <div className="bg-[#aa5042] rounded shadow-lg max-w-md w-full mx-4 flex flex-col max-h-[85vh]">
            {/* Header */}
            <div className="p-5 pb-3 border-b border-[#d8bd8a]/30">
                <div className="flex justify-between items-center mb-3">
                    <h2 className="text-[#efefd1] font-semibold text-base">
                        Defensible Space Questionnaire
                    </h2>
                    <button
                        onClick={() => onComplete(null)}
                        className="text-[#efefd1]/50 hover:text-[#efefd1] text-xs underline transition-colors"
                    >
                        Skip
                    </button>
                </div>
                {/* Progress bar */}
                <div className="flex items-center gap-1.5">
                    {ZONES.map((zone, i) => (
                        <div
                            key={zone.zoneKey}
                            className={`h-1.5 flex-1 rounded-full transition-all duration-300 ${
                                i <= zoneIndex ? "bg-[#d8bd8a]" : "bg-[#d8bd8a]/25"
                            }`}
                        />
                    ))}
                </div>
                <p className="text-[#d8bd8a] text-xs mt-2 font-medium">
                    {currentZone.label}{" "}
                    <span className="text-[#efefd1]/55 font-normal">
                        ({currentZone.rangeLabel})
                    </span>
                </p>
            </div>

            {/* Questions scroll area */}
            <div className="overflow-y-auto flex-1 p-5 space-y-5">
                {currentZone.questions.map((q) => (
                    <QuestionBlock
                        key={q.field}
                        question={q}
                        answers={answers}
                        onSingle={setSingle}
                        onToggleMulti={toggleMulti}
                    />
                ))}
            </div>

            {/* Footer */}
            <div className="p-4 pt-3 border-t border-[#d8bd8a]/30 flex justify-between items-center">
                {zoneIndex > 0 ? (
                    <button
                        onClick={() => setZoneIndex((i) => i - 1)}
                        className="text-[#efefd1]/70 hover:text-[#efefd1] text-sm transition-colors"
                    >
                        ← Back
                    </button>
                ) : (
                    <div />
                )}
                <button
                    onClick={handleNext}
                    className="bg-[#d8bd8a] text-black text-sm font-semibold px-4 py-2 rounded hover:bg-[#c9ae7a] transition-colors"
                >
                    {isLastZone ? "Finish" : "Next Zone →"}
                </button>
            </div>
        </div>
    );
}

function QuestionBlock({
    question,
    answers,
    onSingle,
    onToggleMulti,
}: {
    question: Question;
    answers: QuestionnaireAnswers;
    onSingle: (field: Exclude<keyof QuestionnaireAnswers, "combustible_items_5ft">, value: string) => void;
    onToggleMulti: (value: string) => void;
}) {
    if (question.multi) {
        const selected = answers.combustible_items_5ft ?? [];
        return (
            <div>
                <p className="text-[#efefd1] text-sm mb-1">{question.label}</p>
                {question.description && (
                    <p className="text-[#efefd1]/55 text-xs leading-relaxed mb-1.5">{question.description}</p>
                )}
                <p className="text-[#efefd1]/50 text-xs mb-2">Select all that apply</p>
                <div className="space-y-1.5">
                    {question.options.map((opt) => (
                        <button
                            key={opt.value}
                            onClick={() => onToggleMulti(opt.value)}
                            className={`w-full text-left px-3 py-2 rounded text-sm transition-colors border ${
                                selected.includes(opt.value)
                                    ? "bg-[#d8bd8a] text-black border-[#d8bd8a]"
                                    : "bg-[#8a3d34] text-[#efefd1] border-transparent hover:border-[#d8bd8a]/50"
                            }`}
                        >
                            {opt.label}
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    const current = answers[question.field] as string | null;
    const isTwoOptions = question.options.length === 2;

    return (
        <div>
            <p className="text-[#efefd1] text-sm mb-1">{question.label}</p>
            {question.description && (
                <p className="text-[#efefd1]/55 text-xs leading-relaxed mb-2">{question.description}</p>
            )}
            {isTwoOptions ? (
                <div className="grid grid-cols-2 gap-2">
                    {question.options.map((opt) => (
                        <button
                            key={opt.value}
                            onClick={() => onSingle(question.field, opt.value)}
                            className={`px-3 py-2 rounded text-sm transition-colors border ${
                                current === opt.value
                                    ? "bg-[#d8bd8a] text-black border-[#d8bd8a]"
                                    : "bg-[#8a3d34] text-[#efefd1] border-transparent hover:border-[#d8bd8a]/50"
                            }`}
                        >
                            {opt.label}
                        </button>
                    ))}
                </div>
            ) : (
                <div className="space-y-1.5">
                    {question.options.map((opt) => (
                        <button
                            key={opt.value}
                            onClick={() => onSingle(question.field, opt.value)}
                            className={`w-full text-left px-3 py-2 rounded text-sm transition-colors border ${
                                current === opt.value
                                    ? "bg-[#d8bd8a] text-black border-[#d8bd8a]"
                                    : "bg-[#8a3d34] text-[#efefd1] border-transparent hover:border-[#d8bd8a]/50"
                            }`}
                        >
                            {opt.label}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}

import { useMemo, useState } from "react";
import { STATES } from "../lib/geo";
import { COUNTIES_BY_STATE } from "../lib/counties";
import type { CountyRef } from "../lib/counties";

export type AreaSelection = {
    stateCode: string;
    stateFips: string;
    countyFips: string | null;
    countyName: string | null;
};

function StateCountySelector({
    onConfirm,
}: {
    onConfirm: (selection: AreaSelection) => void;
}) {
    const [selectedState, setSelectedState] = useState<string | null>(null);
    const [selectedCounty, setSelectedCounty] = useState<CountyRef | null>(null);

    const counties = useMemo(
        () => (selectedState ? COUNTIES_BY_STATE[selectedState] ?? [] : []),
        [selectedState],
    );
    const state = STATES.find((s) => s.code === selectedState);

    const canConfirm =
        !!selectedState && (selectedCounty !== null || counties.length === 0);

    return (
        <div className="bg-[#aa5042] p-5 md:p-8 rounded-lg shadow-xl max-w-2xl w-full mx-4 max-h-[90dvh] overflow-y-auto">
            <h2 className="text-[#efefd1] text-2xl font-bold mb-1 text-center">
                Select Your State & County
            </h2>
            <p className="text-[#efefd1] opacity-60 text-sm text-center mb-6">
                Choose the area you want to analyze for fire risk.
            </p>
            <div className="flex flex-col sm:flex-row gap-6">
                {/* State list */}
                <div className="flex-1">
                    <h3 className="text-[#d8bd8a] font-semibold mb-3 text-xs uppercase tracking-widest">
                        State
                    </h3>
                    <div className="space-y-1 max-h-72 overflow-y-auto pr-1">
                        {STATES.map((s) => (
                            <button
                                key={s.code}
                                onClick={() => {
                                    setSelectedState(s.code);
                                    setSelectedCounty(null);
                                }}
                                className={`w-full text-left px-3 py-2 rounded text-sm transition-colors ${
                                    selectedState === s.code
                                        ? "bg-[#d8bd8a] text-black font-semibold"
                                        : "text-[#efefd1] hover:bg-[#c0604e] cursor-pointer"
                                }`}
                            >
                                {s.name}
                            </button>
                        ))}
                    </div>
                </div>

                {/* County list */}
                <div className="flex-1">
                    <h3 className="text-[#d8bd8a] font-semibold mb-3 text-xs uppercase tracking-widest">
                        County
                    </h3>
                    {!selectedState ? (
                        <p className="text-[#efefd1] opacity-40 text-sm italic mt-2">
                            Select a state first
                        </p>
                    ) : counties.length === 0 ? (
                        <p className="text-[#efefd1] opacity-40 text-sm italic mt-2">
                            No county data available — you can still continue
                        </p>
                    ) : (
                        <div className="space-y-1 max-h-72 overflow-y-auto pr-1">
                            {counties.map((county) => (
                                <button
                                    key={county.fips}
                                    onClick={() => setSelectedCounty(county)}
                                    className={`w-full text-left px-3 py-2 rounded text-sm transition-colors ${
                                        selectedCounty?.fips === county.fips
                                            ? "bg-[#d8bd8a] text-black font-semibold"
                                            : "text-[#efefd1] hover:bg-[#c0604e]"
                                    }`}
                                >
                                    {county.name}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            <div className="mt-6 flex justify-end">
                <button
                    onClick={() => {
                        if (!state) return;
                        onConfirm({
                            stateCode: state.code,
                            stateFips: state.fips,
                            countyFips: selectedCounty?.fips ?? null,
                            countyName: selectedCounty?.name ?? null,
                        });
                    }}
                    disabled={!canConfirm}
                    className={`px-6 py-2 rounded font-semibold transition-colors ${
                        canConfirm
                            ? "bg-[#d8bd8a] text-black hover:bg-[#c9ae7a] cursor-pointer"
                            : "bg-[#d8bd8a] opacity-40 text-black cursor-not-allowed"
                    }`}
                >
                    Continue
                </button>
            </div>
        </div>
    );
}

export default StateCountySelector;

// Eagerly load all markdown files from the posts directory at build time.
// Vite resolves this glob statically — no dynamic imports at runtime.
const rawFiles = import.meta.glob("../blog/posts/*.md", {
    query: "?raw",
    import: "default",
    eager: true,
}) as Record<string, string>;

export interface PostMeta {
    slug: string;
    title: string;
    date: string;         // ISO date string, e.g. "2026-05-11"
    description: string;
}

export interface Post extends PostMeta {
    content: string;      // raw markdown body (without frontmatter)
}

/**
 * Minimal YAML frontmatter parser — handles simple key: value pairs only.
 * Avoids gray-matter / js-yaml which require Buffer (Node.js only).
 */
function parseFrontmatter(raw: string): { data: Record<string, string>; content: string } {
    const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
    if (!match) return { data: {}, content: raw };
    const data: Record<string, string> = {};
    for (const line of match[1].split(/\r?\n/)) {
        const colon = line.indexOf(":");
        if (colon === -1) continue;
        const key = line.slice(0, colon).trim();
        const value = line.slice(colon + 1).trim();
        if (key) data[key] = value;
    }
    return { data, content: match[2] };
}

function parsePost(raw: string, filePath: string): Post {
    const { data, content } = parseFrontmatter(raw);
    const slug =
        data.slug ||
        filePath
            .split("/")
            .pop()!
            .replace(/\.md$/, "");
    return {
        slug,
        title: data.title ?? "Untitled",
        date: data.date ?? "",
        description: data.description ?? "",
        content,
    };
}

function getSortedPosts(): Post[] {
    return Object.entries(rawFiles)
        .map(([path, raw]) => parsePost(raw, path))
        .sort((a, b) => (a.date < b.date ? 1 : -1));
}

export function getAllPosts(): PostMeta[] {
    return getSortedPosts().map(({ content: _c, ...meta }) => meta);
}

export function getPostBySlug(slug: string): Post | undefined {
    return getSortedPosts().find((p) => p.slug === slug);
}

